create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
create table public.profiles (
 id uuid primary key references auth.users(id), username text not null unique,
 role text not null default 'visitor' check(role in ('admin','visitor')), active boolean not null default true,
 must_change_password boolean not null default true, password_changed_at timestamptz,
 avatar_code bigint generated always as identity unique, avatar jsonb not null default '{}', avatar_path text,
 settings jsonb not null default '{"theme":"system","language":"zh-CN"}', created_at timestamptz not null default now()
);
create table public.invites(id uuid primary key default gen_random_uuid(), digest text unique not null, label text not null default '',max_uses int not null check(max_uses>0),used int not null default 0,expires_at timestamptz not null,revoked boolean not null default false,created_by uuid references public.profiles,created_at timestamptz default now());
create table public.exams(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles,title text not null check(length(trim(title))>0),description text not null default '',subject text not null default '',tags jsonb not null default '[]',status text not null default 'draft' check(status in ('draft','pending','returned','published','unpublished','deleted')),revision int not null default 0,questions jsonb not null default '[]',time_limit int not null default 0 check(time_limit>=0),repeat_allowed boolean not null default true,reveal_answers boolean not null default true,show_explanations boolean not null default true,published_version_id uuid,review_reason text,deleted_at timestamptz,deleted_by uuid references public.profiles,updated_at timestamptz not null default now(),created_at timestamptz not null default now());
create table public.exam_versions(id uuid primary key default gen_random_uuid(),exam_id uuid not null references public.exams,number int not null,snapshot jsonb not null,max_score numeric not null,created_at timestamptz default now(),unique(exam_id,number));
alter table public.exams add foreign key(published_version_id) references public.exam_versions;
create table public.reviews(id uuid primary key default gen_random_uuid(),exam_id uuid references public.exams,actor_id uuid references public.profiles,action text not null,reason text,created_at timestamptz default now());
create table public.attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,exam_id uuid not null references public.exams,exam_version_id uuid not null references public.exam_versions,started_at timestamptz not null default now(),submitted_at timestamptz,duration_seconds int,answers jsonb not null default '{}',revision int not null default 0,score numeric,max_score numeric not null,grades jsonb,grading_status text not null default 'in_progress' check(grading_status in ('in_progress','pending','final')),comments jsonb not null default '{}');
create unique index one_open_attempt on public.attempts(user_id,exam_version_id) where submitted_at is null;
create index attempts_history on public.attempts(user_id,submitted_at desc);
create index attempts_ranking on public.attempts(exam_version_id,score desc,duration_seconds,submitted_at) where grading_status='final';
create index exams_owner on public.exams(owner_id,updated_at desc);
create table public.files(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles,purpose text not null check(purpose in ('attachment','submission','shared','avatar','conversion')),name text not null,mime text not null,size bigint not null check(size between 1 and 50000000),path text unique not null,exam_id uuid references public.exams,attempt_id uuid references public.attempts,description text not null default '',category text not null default '',verified boolean not null default false,created_at timestamptz default now());
create index files_owner on public.files(owner_id,purpose);
create table public.conversion_jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,input_file_id uuid not null references public.files,target text not null,status text not null default 'queued' check(status in ('queued','running','completed','failed','cancelled')),output_path text,error text,lease_id uuid,lease_until timestamptz,created_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '24 hours');
create index conversion_queue on public.conversion_jobs(status,created_at);
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references public.profiles,event text not null,entity_id text,details jsonb not null default '{}',created_at timestamptz default now());
create table public.system_config(key text primary key,value jsonb not null);
create table private.rate_limits(key text primary key,window_at timestamptz not null default now(),hits int not null default 1);
create table private.registrations(username text primary key,invite_id uuid references public.invites,user_id uuid unique,created_at timestamptz default now());
create table private.bootstrap(token_hash text not null,used boolean not null default false);
alter table private.rate_limits enable row level security;
alter table private.registrations enable row level security;
alter table private.bootstrap enable row level security;
do $$ declare t text; begin foreach t in array array['profiles','invites','exams','exam_versions','reviews','attempts','files','conversion_jobs','audit_logs','system_config'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
grant usage on schema private to service_role;
grant all on all tables in schema private to service_role;
grant usage,select on all sequences in schema public to service_role;
create function private.guard_signup() returns trigger language plpgsql set search_path='' as $$begin if coalesce(new.raw_app_meta_data->>'provisioned','')<>'mango-v1' then raise exception 'Invite registration required';end if;return new;end$$;
create trigger require_provisioned_signup before insert on auth.users for each row execute function private.guard_signup();
create function public.api_rate_limit(p_key text,p_limit int,p_seconds int) returns boolean language plpgsql set search_path='' as $$declare n int;begin insert into private.rate_limits as r(key) values(p_key) on conflict(key) do update set hits=case when r.window_at<now()-make_interval(secs=>p_seconds) then 1 else r.hits+1 end,window_at=case when r.window_at<now()-make_interval(secs=>p_seconds) then now() else r.window_at end returning hits into n;return n<=p_limit;end$$;
create function public.api_reserve_registration(p_username text,p_digest text) returns uuid language plpgsql set search_path='' as $$declare inv public.invites;begin select * into inv from public.invites where digest=p_digest for update;if inv.id is null or inv.revoked or inv.expires_at<=now() or inv.used>=inv.max_uses then raise exception '密令无效、过期或已用尽';end if;if p_username='admin' then raise exception '保留账号名';end if;insert into private.registrations(username,invite_id) values(p_username,inv.id);update public.invites set used=used+1 where id=inv.id;return inv.id;end$$;
create function public.api_release_registration(p_username text) returns void language plpgsql set search_path='' as $$declare inv uuid;begin delete from private.registrations where username=p_username and user_id is null returning invite_id into inv;if inv is not null then update public.invites set used=greatest(0,used-1) where id=inv;end if;end$$;
create function public.api_save_exam(p_id uuid,p_actor uuid,p_revision int,p_data jsonb) returns public.exams language plpgsql set search_path='' as $$declare e public.exams;begin select * into e from public.exams where id=p_id for update;if e.id is null then raise exception '试卷不存在';end if;if e.owner_id<>p_actor and not exists(select 1 from public.profiles where id=p_actor and role='admin' and active) then raise exception '无权限';end if;if e.revision<>p_revision then raise exception 'CONFLICT:试卷有新版本，请保留本地内容后重新载入';end if;if e.status='deleted' then raise exception '试卷在回收站';end if;update public.exams set title=p_data->>'title',description=coalesce(p_data->>'description',''),subject=coalesce(p_data->>'subject',''),tags=coalesce(p_data->'tags','[]'),questions=p_data->'questions',time_limit=(p_data->>'time_limit')::int,repeat_allowed=(p_data->>'repeat_allowed')::boolean,reveal_answers=(p_data->>'reveal_answers')::boolean,show_explanations=(p_data->>'show_explanations')::boolean,status='draft',revision=revision+1,updated_at=now() where id=p_id returning * into e;return e;end$$;
create function public.api_review_exam(p_id uuid,p_actor uuid,p_action text,p_reason text) returns public.exams language plpgsql set search_path='' as $$declare e public.exams;v uuid;n int;begin if not exists(select 1 from public.profiles where id=p_actor and role='admin' and active) then raise exception '无权限';end if;select * into e from public.exams where id=p_id for update;if e.id is null then raise exception '不存在';end if;if p_action='publish' then if e.status<>'pending' then raise exception '必须先提交审核';end if;select coalesce(max(number),0)+1 into n from public.exam_versions where exam_id=p_id;insert into public.exam_versions(exam_id,number,snapshot,max_score) values(p_id,n,to_jsonb(e),(select sum((x->>'points')::numeric) from jsonb_array_elements(e.questions)x)) returning id into v;update public.exams set status='published',published_version_id=v where id=p_id;elsif p_action='return' then if length(trim(p_reason))=0 then raise exception '请填写退回原因';end if;update public.exams set status='returned',review_reason=p_reason where id=p_id;elsif p_action='unpublish' then update public.exams set status='unpublished' where id=p_id;elsif p_action='restore' then update public.exams set status='draft',deleted_at=null,deleted_by=null where id=p_id and status='deleted';else raise exception '无效操作';end if;insert into public.reviews(exam_id,actor_id,action,reason)values(p_id,p_actor,p_action,p_reason);select * into e from public.exams where id=p_id;return e;end$$;
create function public.api_start_attempt(p_exam uuid,p_user uuid) returns public.attempts language plpgsql set search_path='' as $$declare e public.exams;a public.attempts;v public.exam_versions;begin perform pg_advisory_xact_lock(hashtextextended(p_user::text||p_exam::text,0));select * into e from public.exams where id=p_exam and status='published';if e.id is null then raise exception '试卷未发布';end if;select * into a from public.attempts where user_id=p_user and exam_version_id=e.published_version_id and submitted_at is null;if a.id is not null then return a;end if;if not e.repeat_allowed and exists(select 1 from public.attempts where user_id=p_user and exam_version_id=e.published_version_id) then raise exception '本试卷不允许重复答题';end if;select * into v from public.exam_versions where id=e.published_version_id;insert into public.attempts(user_id,exam_id,exam_version_id,max_score)values(p_user,p_exam,v.id,v.max_score)returning * into a;return a;end$$;
create function public.api_save_attempt(p_id uuid,p_user uuid,p_revision int,p_answers jsonb,p_submit boolean,p_result jsonb default null) returns public.attempts language plpgsql set search_path='' as $$declare a public.attempts;begin select * into a from public.attempts where id=p_id and user_id=p_user for update;if a.id is null then raise exception '答卷不存在';end if;if a.submitted_at is not null then return a;end if;if a.revision<>p_revision then raise exception 'CONFLICT:其他设备已有新答案';end if;update public.attempts set answers=p_answers,revision=revision+1,submitted_at=case when p_submit then clock_timestamp() else null end,duration_seconds=case when p_submit then greatest(0,floor(extract(epoch from clock_timestamp()-started_at)))::int else null end,score=case when p_submit then (p_result->>'score')::numeric else null end,grades=case when p_submit then p_result->'grades' else null end,grading_status=case when p_submit then p_result->>'grading_status' else 'in_progress' end where id=p_id returning * into a;return a;end$$;
create function public.api_leaderboard(p_version uuid,p_limit int default 50,p_offset int default 0) returns table(username text,score numeric,max_score numeric,duration_seconds int,rank bigint) language sql set search_path='' as $$with best as(select distinct on (a.user_id) a.user_id,a.score,a.max_score,a.duration_seconds,a.submitted_at,a.id from public.attempts a join public.profiles p on p.id=a.user_id where a.exam_version_id=p_version and a.grading_status='final' and p.active order by a.user_id,a.score desc,a.duration_seconds,a.submitted_at,a.id),ranked as(select p.username,b.score,b.max_score,b.duration_seconds,dense_rank()over(order by b.score desc,b.duration_seconds)rank,b.submitted_at,b.id from best b join public.profiles p on p.id=b.user_id)select r.username,r.score,r.max_score,r.duration_seconds,r.rank from ranked r order by r.score desc,r.duration_seconds,r.submitted_at,r.id limit least(p_limit,100) offset greatest(0,p_offset)$$;
do $$declare f record;begin for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'api_%' loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;end$$;
insert into storage.buckets(id,name,public,file_size_limit) values('mango-private','mango-private',false,50000000);
-- No Storage client policies: uploads and signed downloads are authorized by the API.
